function [q] = boresight_offset(bs_in)
%BORESIGHT_OFFSET  The rotation taking +Y_B (the nadir axis of the base frame) to the payload axis.
%   bs_in: real[1][3] (passed a plain number)
%   returns q: real[1][4] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    q = zeros(4, 1);
    ey = [0; 1; 0];
    h__614 = sqrt(bs_in(1)*bs_in(1) + bs_in(2)*bs_in(2) + bs_in(3)*bs_in(3));
    if 1e-30 > h__614, h__614 = 1e-30; end
    bs = (bs_in / h__614);
    ax = [ey(2)*bs(3) - ey(3)*bs(2); ey(3)*bs(1) - ey(1)*bs(3); ey(1)*bs(2) - ey(2)*bs(1)];
    c = (ey(1)*bs(1) + ey(2)*bs(2) + ey(3)*bs(3));
    s = sqrt(ax(1)*ax(1) + ax(2)*ax(2) + ax(3)*ax(3));
    if (s < 1e-12)
        q = [0; 0; 0; 1];
        if (c <= 0)
            q = [1; 0; 0; 0];
        end
    else
        k = (ax * (1 / s));
        kk = asils.models.math.skew(k);
        k2 = asils.pc.mm(kk, kk);
        a = zeros(3, 3);
        i = ((0):((3) - 1)).';
        j = (0):((3) - 1);
        a((i) + 1, (j) + 1) = ((asils.pc.vchoose((i == j), 1, 0) + (s .* kk((i) + 1, (j) + 1))) + ((1 - c) .* k2((i) + 1, (j) + 1)));
        q = asils.models.math.fromdcm(a);
    end
end
